// The current verification status of an Auth Item initiated through Automated or Manual micro-deposits.  Returned for Auth Items only.
//
// `pending_automatic_verification`: The Item is pending automatic verification.
//
// `pending_manual_verification`: The Item is pending manual micro-deposit verification. Items remain in this state until the user successfully verifies the micro-deposit.
//
// `automatically_verified`: The Item has successfully been automatically verified.
//
// `manually_verified`: The Item has successfully been manually verified.
//
// `verification_expired`: Plaid was unable to automatically verify the deposit within 7 calendar days and will no longer attempt to validate the Item. Users may retry by submitting their information again through Link.
//
// `verification_failed`: The Item failed manual micro-deposit verification because the user exhausted all 3 verification attempts. Users may retry by submitting their information again through Link.
//
// `database_matched`: (deprecated) The Item has successfully been verified using Plaid's data sources. Only returned for Auth Items created via Database Match.
type AccountAssetsVerificationStatus string

const (
	AccountAssetsVerificationStatusAutomaticallyVerified        AccountAssetsVerificationStatus = "automatically_verified"
	AccountAssetsVerificationStatusPendingAutomaticVerification AccountAssetsVerificationStatus = "pending_automatic_verification"
	AccountAssetsVerificationStatusPendingManualVerification    AccountAssetsVerificationStatus = "pending_manual_verification"
	AccountAssetsVerificationStatusManuallyVerified             AccountAssetsVerificationStatus = "manually_verified"
	AccountAssetsVerificationStatusVerificationExpired          AccountAssetsVerificationStatus = "verification_expired"
	AccountAssetsVerificationStatusVerificationFailed           AccountAssetsVerificationStatus = "verification_failed"
	AccountAssetsVerificationStatusDatabaseMatched              AccountAssetsVerificationStatus = "database_matched"
)

func NewAccountAssetsVerificationStatusFromString(s string) (AccountAssetsVerificationStatus, error) {
	switch s {
	case "automatically_verified":
		return AccountAssetsVerificationStatusAutomaticallyVerified, nil
	case "pending_automatic_verification":
		return AccountAssetsVerificationStatusPendingAutomaticVerification, nil
	case "pending_manual_verification":
		return AccountAssetsVerificationStatusPendingManualVerification, nil
	case "manually_verified":
		return AccountAssetsVerificationStatusManuallyVerified, nil
	case "verification_expired":
		return AccountAssetsVerificationStatusVerificationExpired, nil
	case "verification_failed":
		return AccountAssetsVerificationStatusVerificationFailed, nil
	case "database_matched":
		return AccountAssetsVerificationStatusDatabaseMatched, nil
	}
	var t AccountAssetsVerificationStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (a AccountAssetsVerificationStatus) Ptr() *AccountAssetsVerificationStatus {
	return &a
}

