const (
	AssetReportTransactionTypeDigital    AssetReportTransactionType = "digital"
	AssetReportTransactionTypePlace      AssetReportTransactionType = "place"
	AssetReportTransactionTypeSpecial    AssetReportTransactionType = "special"
	AssetReportTransactionTypeUnresolved AssetReportTransactionType = "unresolved"
)

func NewAssetReportTransactionTypeFromString(s string) (AssetReportTransactionType, error) {
	switch s {
	case "digital":
		return AssetReportTransactionTypeDigital, nil
	case "place":
		return AssetReportTransactionTypePlace, nil
	case "special":
		return AssetReportTransactionTypeSpecial, nil
	case "unresolved":
		return AssetReportTransactionTypeUnresolved, nil
	}
	var t AssetReportTransactionType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

