// `digital:` transactions that took place online.
//
// `place:` transactions that were made at a physical location.
//
// `special:` transactions that relate to banks, e.g. fees or deposits.
//
// `unresolved:` transactions that do not fit into the other types.
type BaseReportTransactionType string

const (
	BaseReportTransactionTypeDigital    BaseReportTransactionType = "digital"
	BaseReportTransactionTypePlace      BaseReportTransactionType = "place"
	BaseReportTransactionTypeSpecial    BaseReportTransactionType = "special"
	BaseReportTransactionTypeUnresolved BaseReportTransactionType = "unresolved"
)

func NewBaseReportTransactionTypeFromString(s string) (BaseReportTransactionType, error) {
	switch s {
	case "digital":
		return BaseReportTransactionTypeDigital, nil
	case "place":
		return BaseReportTransactionTypePlace, nil
	case "special":
		return BaseReportTransactionTypeSpecial, nil
	case "unresolved":
		return BaseReportTransactionTypeUnresolved, nil
	}
	var t BaseReportTransactionType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (b BaseReportTransactionType) Ptr() *BaseReportTransactionType {
	return &b
}

