// The type of Beacon Report.
//
// `first_party`: If this is the same individual as the one who submitted the KYC.
//
// `stolen`: If this is a different individual from the one who submitted the KYC.
//
// `synthetic`: If this is an individual using fabricated information.
//
// `account_takeover`: If this individual's account was compromised.
//
// `data_breach`: If this individual's data was compromised in a breach.
//
// `unknown`: If you aren't sure who committed the fraud.
type BeaconReportType string

const (
	BeaconReportTypeFirstParty      BeaconReportType = "first_party"
	BeaconReportTypeStolen          BeaconReportType = "stolen"
	BeaconReportTypeSynthetic       BeaconReportType = "synthetic"
	BeaconReportTypeAccountTakeover BeaconReportType = "account_takeover"
	BeaconReportTypeDataBreach      BeaconReportType = "data_breach"
	BeaconReportTypeUnknown         BeaconReportType = "unknown"
)

func NewBeaconReportTypeFromString(s string) (BeaconReportType, error) {
	switch s {
	case "first_party":
		return BeaconReportTypeFirstParty, nil
	case "stolen":
		return BeaconReportTypeStolen, nil
	case "synthetic":
		return BeaconReportTypeSynthetic, nil
	case "account_takeover":
		return BeaconReportTypeAccountTakeover, nil
	case "data_breach":
		return BeaconReportTypeDataBreach, nil
	case "unknown":
		return BeaconReportTypeUnknown, nil
	}
	var t BeaconReportType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

