// An insight that can be detected by the Cash Flow Updates product
type CashFlowInsight string

const (
	CashFlowInsightLargeDepositDetected   CashFlowInsight = "LARGE_DEPOSIT_DETECTED"
	CashFlowInsightLowBalanceDetected     CashFlowInsight = "LOW_BALANCE_DETECTED"
	CashFlowInsightNewLoanPaymentDetected CashFlowInsight = "NEW_LOAN_PAYMENT_DETECTED"
	CashFlowInsightNsfOverdraftDetected   CashFlowInsight = "NSF_OVERDRAFT_DETECTED"
)

func NewCashFlowInsightFromString(s string) (CashFlowInsight, error) {
	switch s {
	case "LARGE_DEPOSIT_DETECTED":
		return CashFlowInsightLargeDepositDetected, nil
	case "LOW_BALANCE_DETECTED":
		return CashFlowInsightLowBalanceDetected, nil
	case "NEW_LOAN_PAYMENT_DETECTED":
		return CashFlowInsightNewLoanPaymentDetected, nil
	case "NSF_OVERDRAFT_DETECTED":
		return CashFlowInsightNsfOverdraftDetected, nil
	}
	var t CashFlowInsight
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (c CashFlowInsight) Ptr() *CashFlowInsight {
	return &c
}

