const (
	EmailTypePrimary   EmailType = "primary"
	EmailTypeSecondary EmailType = "secondary"
	EmailTypeOther     EmailType = "other"
)

func NewEmailTypeFromString(s string) (EmailType, error) {
	switch s {
	case "primary":
		return EmailTypePrimary, nil
	case "secondary":
		return EmailTypeSecondary, nil
	case "other":
		return EmailTypeOther, nil
	}
	var t EmailType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

