// A binary match indicator specifying whether the country that issued the provided document matches the country that the user separately provided to Plaid.
//
// Note: You can configure whether a `no_match` on `issuing_country` fails the `documentary_verification` by editing your Plaid Template.
type IssuingCountry string

const (
	IssuingCountryMatch   IssuingCountry = "match"
	IssuingCountryNoMatch IssuingCountry = "no_match"
)

func NewIssuingCountryFromString(s string) (IssuingCountry, error) {
	switch s {
	case "match":
		return IssuingCountryMatch, nil
	case "no_match":
		return IssuingCountryNoMatch, nil
	}
	var t IssuingCountry
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (i IssuingCountry) Ptr() *IssuingCountry {
	return &i
}

