//
// `background` - Item can be updated in the background
//
// `user_present_required` - Item requires user interaction to be updated
type ItemUpdateType string

const (
	ItemUpdateTypeBackground          ItemUpdateType = "background"
	ItemUpdateTypeUserPresentRequired ItemUpdateType = "user_present_required"
)

func NewItemUpdateTypeFromString(s string) (ItemUpdateType, error) {
	switch s {
	case "background":
		return ItemUpdateTypeBackground, nil
	case "user_present_required":
		return ItemUpdateTypeUserPresentRequired, nil
	}
	var t ItemUpdateType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

