// The frequency at which interest is compounded.
type LoanCompoundingPeriod string

const (
	LoanCompoundingPeriodDaily        LoanCompoundingPeriod = "daily"
	LoanCompoundingPeriodWeekly       LoanCompoundingPeriod = "weekly"
	LoanCompoundingPeriodBiweekly     LoanCompoundingPeriod = "biweekly"
	LoanCompoundingPeriodSemimonthly  LoanCompoundingPeriod = "semimonthly"
	LoanCompoundingPeriodMonthly      LoanCompoundingPeriod = "monthly"
	LoanCompoundingPeriodSemiannually LoanCompoundingPeriod = "semiannually"
	LoanCompoundingPeriodAnnually     LoanCompoundingPeriod = "annually"
)

func NewLoanCompoundingPeriodFromString(s string) (LoanCompoundingPeriod, error) {
	switch s {
	case "daily":
		return LoanCompoundingPeriodDaily, nil
	case "weekly":
		return LoanCompoundingPeriodWeekly, nil
	case "biweekly":
		return LoanCompoundingPeriodBiweekly, nil
	case "semimonthly":
		return LoanCompoundingPeriodSemimonthly, nil
	case "monthly":
		return LoanCompoundingPeriodMonthly, nil
	case "semiannually":
		return LoanCompoundingPeriodSemiannually, nil
	case "annually":
		return LoanCompoundingPeriodAnnually, nil
	}
	var t LoanCompoundingPeriod
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

