// Describes the frequency of the transaction stream.
//
// `WEEKLY`: Assigned to a transaction stream that occurs approximately every week.
//
// `BIWEEKLY`: Assigned to a transaction stream that occurs approximately every 2 weeks.
//
// `SEMI_MONTHLY`: Assigned to a transaction stream that occurs approximately twice per month. This frequency is typically seen for inflow transaction streams.
//
// `MONTHLY`: Assigned to a transaction stream that occurs approximately every month.
//
// `ANNUALLY`: Assigned to a transaction stream that occurs approximately every year.
//
// `UNKNOWN`: Assigned to a transaction stream that does not fit any of the pre-defined frequencies.
type RecurringTransactionFrequency string

const (
	RecurringTransactionFrequencyUnknown     RecurringTransactionFrequency = "UNKNOWN"
	RecurringTransactionFrequencyWeekly      RecurringTransactionFrequency = "WEEKLY"
	RecurringTransactionFrequencyBiweekly    RecurringTransactionFrequency = "BIWEEKLY"
	RecurringTransactionFrequencySemiMonthly RecurringTransactionFrequency = "SEMI_MONTHLY"
	RecurringTransactionFrequencyMonthly     RecurringTransactionFrequency = "MONTHLY"
	RecurringTransactionFrequencyAnnually    RecurringTransactionFrequency = "ANNUALLY"
)

func NewRecurringTransactionFrequencyFromString(s string) (RecurringTransactionFrequency, error) {
	switch s {
	case "UNKNOWN":
		return RecurringTransactionFrequencyUnknown, nil
	case "WEEKLY":
		return RecurringTransactionFrequencyWeekly, nil
	case "BIWEEKLY":
		return RecurringTransactionFrequencyBiweekly, nil
	case "SEMI_MONTHLY":
		return RecurringTransactionFrequencySemiMonthly, nil
	case "MONTHLY":
		return RecurringTransactionFrequencyMonthly, nil
	case "ANNUALLY":
		return RecurringTransactionFrequencyAnnually, nil
	}
	var t RecurringTransactionFrequency
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (r RecurringTransactionFrequency) Ptr() *RecurringTransactionFrequency {
	return &r
}

