// The payment method to complete the transaction after the risk assessment. It may be different from the default payment method.
//
// `SAME_DAY_ACH`: Same Day ACH by Nacha. The debit transaction is processed and settled on the same day.
//
// `STANDARD_ACH`: Standard ACH by Nacha.
//
// `MULTIPLE_PAYMENT_METHODS`: if there is no default debit rail or there are multiple payment methods.
type SignalPaymentMethod string

const (
	SignalPaymentMethodSameDayAch             SignalPaymentMethod = "SAME_DAY_ACH"
	SignalPaymentMethodNextDayAch             SignalPaymentMethod = "NEXT_DAY_ACH"
	SignalPaymentMethodStandardAch            SignalPaymentMethod = "STANDARD_ACH"
	SignalPaymentMethodMultiplePaymentMethods SignalPaymentMethod = "MULTIPLE_PAYMENT_METHODS"
)

func NewSignalPaymentMethodFromString(s string) (SignalPaymentMethod, error) {
	switch s {
	case "SAME_DAY_ACH":
		return SignalPaymentMethodSameDayAch, nil
	case "NEXT_DAY_ACH":
		return SignalPaymentMethodNextDayAch, nil
	case "STANDARD_ACH":
		return SignalPaymentMethodStandardAch, nil
	case "MULTIPLE_PAYMENT_METHODS":
		return SignalPaymentMethodMultiplePaymentMethods, nil
	}
	var t SignalPaymentMethod
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (s SignalPaymentMethod) Ptr() *SignalPaymentMethod {
	return &s
}

