// The status of the transfer intent.
//
// `PENDING`: The transfer intent is pending.
//
// `SUCCEEDED`: The transfer intent was successfully created.
//
// `FAILED`: The transfer intent was unable to be created.
type TransferIntentStatus string

const (
	TransferIntentStatusPending   TransferIntentStatus = "PENDING"
	TransferIntentStatusSucceeded TransferIntentStatus = "SUCCEEDED"
	TransferIntentStatusFailed    TransferIntentStatus = "FAILED"
)

func NewTransferIntentStatusFromString(s string) (TransferIntentStatus, error) {
	switch s {
	case "PENDING":
		return TransferIntentStatusPending, nil
	case "SUCCEEDED":
		return TransferIntentStatusSucceeded, nil
	case "FAILED":
		return TransferIntentStatusFailed, nil
	}
	var t TransferIntentStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (t TransferIntentStatus) Ptr() *TransferIntentStatus {
	return &t
}

